import type { Core } from '@strapi/strapi';
import { errors } from '@strapi/utils';

const UID = 'api::form-field.form-field';
const ACTIONS = ['create', 'update', 'publish'];

export interface FormFieldIntegrityInput {
  key?: string | null;
  countryDocumentId?: string | null;
  selfDocumentId?: string | null;
}

export interface ExistingKey {
  documentId: string;
  key: string;
}

/** Pure rule: a field needs a country, and its key is unique within that country. */
export function checkFormFieldIntegrity(
  input: FormFieldIntegrityInput,
  existingSameCountryKeys: ExistingKey[],
): string | null {
  if (!input.countryDocumentId) return 'El campo debe tener un país.';
  const duplicate = existingSameCountryKeys.some(
    (f) => f.key === input.key && f.documentId !== input.selfDocumentId,
  );
  if (duplicate) return `Ya existe un campo con la clave «${input.key}» para este país.`;
  return null;
}

type Ref = string | number;

function refOf(item: unknown): Ref | null {
  if (typeof item === 'string' || typeof item === 'number') return item;
  if (item && typeof item === 'object') {
    const o = item as Record<string, unknown>;
    return (o.documentId ?? o.id ?? null) as Ref | null;
  }
  return null;
}

/** Reads the country from the relation payload shapes Strapi accepts. `present=false` means untouched. */
export function readCountryPayload(value: unknown): { present: boolean; ref: Ref | null } {
  if (value === undefined) return { present: false, ref: null };
  if (value === null) return { present: true, ref: null };
  if (typeof value === 'string' || typeof value === 'number') return { present: true, ref: value };
  if (typeof value === 'object') {
    const v = value as Record<string, unknown>;
    // `set` replaces the relation: an empty set clears it.
    if (Array.isArray(v.set)) return { present: true, ref: refOf(v.set[0]) };
    if (Array.isArray(v.connect) && v.connect.length > 0) return { present: true, ref: refOf(v.connect[0]) };
    if (Array.isArray(v.disconnect) && v.disconnect.length > 0) return { present: true, ref: null };
    // The admin sends `{ connect: [], disconnect: [] }` when the relation is left as is.
    if (Array.isArray(v.connect) || Array.isArray(v.disconnect)) return { present: false, ref: null };
    if (v.documentId !== undefined || v.id !== undefined) return { present: true, ref: refOf(v) };
  }
  return { present: false, ref: null };
}

export function registerFormFieldIntegrity(strapi: Core.Strapi): void {
  strapi.documents.use(async (context, next) => {
    if (context.uid !== UID || !ACTIONS.includes(context.action)) return next();

    const params = (context.params ?? {}) as { documentId?: string; data?: Record<string, unknown> };
    const data = params.data ?? {};
    const selfDocumentId = params.documentId ?? null;

    type Existing = { key?: string; country?: { documentId: string } | null } | null;
    let existing = null as Existing;
    if (selfDocumentId) {
      existing = (await strapi.documents(UID).findOne({
        documentId: selfDocumentId,
        populate: { country: { fields: ['documentId'] } },
        status: 'draft',
      })) as Existing;
    }

    const key = (data.key as string | undefined) ?? existing?.key ?? null;

    const { present, ref } = readCountryPayload(data.country);
    let countryDocumentId: string | null = null;
    if (present) {
      if (typeof ref === 'number') {
        const found = (await strapi.db.query('api::country.country').findOne({ where: { id: ref } })) as {
          documentId: string;
        } | null;
        countryDocumentId = found?.documentId ?? null;
      } else {
        countryDocumentId = ref;
      }
    } else {
      countryDocumentId = existing?.country?.documentId ?? null;
    }

    let others: ExistingKey[] = [];
    if (countryDocumentId) {
      // Draft and published versions share a documentId, so excluding it covers both.
      others = (await strapi.documents(UID).findMany({
        filters: { country: { documentId: countryDocumentId } },
        fields: ['key'],
        status: 'draft',
      })) as ExistingKey[];
    }

    const message = checkFormFieldIntegrity({ key, countryDocumentId, selfDocumentId }, others);
    if (message) throw new errors.ValidationError(message);
    return next();
  });
}
import { describe, expect, it } from 'vitest';
import { checkFormFieldIntegrity, readCountryPayload } from './form-field-integrity';

describe('US-01 · Edge Cases form field integrity', () => {
  const existing = [
    { documentId: 'a1', key: 'plate' },
    { documentId: 'a2', key: 'email' },
  ];

  it('rejects a field without country', () => {
    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: null }, [])).toBe('El campo debe tener un país.');
  });

  it('rejects a duplicate key in the same country', () => {
    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'co', selfDocumentId: 'new' }, existing)).toBe(
      'Ya existe un campo con la clave «plate» para este país.',
    );
  });

  it('allows the same key in another country', () => {
    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'cl' }, [])).toBeNull();
  });

  it('allows an update that keeps its own key', () => {
    expect(
      checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'co', selfDocumentId: 'a1' }, existing),
    ).toBeNull();
  });

  it('allows a valid new field', () => {
    expect(checkFormFieldIntegrity({ key: 'city', countryDocumentId: 'co' }, existing)).toBeNull();
  });

  it('reads the relation payload shapes', () => {
    expect(readCountryPayload(undefined)).toEqual({ present: false, ref: null });
    expect(readCountryPayload('abc')).toEqual({ present: true, ref: 'abc' });
    expect(readCountryPayload({ connect: [{ documentId: 'abc' }] })).toEqual({ present: true, ref: 'abc' });
    expect(readCountryPayload({ set: ['abc'] })).toEqual({ present: true, ref: 'abc' });
    expect(readCountryPayload({ set: [] })).toEqual({ present: true, ref: null });
    expect(readCountryPayload({ connect: [], disconnect: [{ id: 1 }] })).toEqual({ present: true, ref: null });
    expect(readCountryPayload(3)).toEqual({ present: true, ref: 3 });
  });
});

describe('US-01 · FR-001 admin edits keep the country (Gate 3 manual test)', () => {
  it('reads the untouched relation from the admin as no change, so editing another attribute is allowed', () => {
    expect(readCountryPayload({ connect: [], disconnect: [] })).toEqual({ present: false, ref: null });
    expect(readCountryPayload({ connect: [] })).toEqual({ present: false, ref: null });
  });

  it('reads a country changed in the admin (disconnect old, connect new)', () => {
    expect(
      readCountryPayload({ connect: [{ id: 2, documentId: 'cl' }], disconnect: [{ id: 1, documentId: 'co' }] }),
    ).toEqual({ present: true, ref: 'cl' });
  });
});

import type { Core } from '@strapi/strapi';
import { registerFormFieldIntegrity } from './middlewares/form-field-integrity';
import { seedAdmin } from './seed/admin';
import { seedCountries } from './seed/countries';
import { backfillLegalAge, seedFormFields } from './seed/form-fields';
import { grantPublicPermissions } from './seed/permissions';

export default {
  register({ strapi }: { strapi: Core.Strapi }) {
    registerFormFieldIntegrity(strapi);
  },

  // Idempotent: safe to run on every start.
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    await grantPublicPermissions(strapi);
    await seedCountries(strapi);
    await backfillLegalAge(strapi);
    await seedFormFields(strapi);
    await seedAdmin(strapi);
  },
};
import fs from 'node:fs';
import path from 'node:path';
import type { Core } from '@strapi/strapi';

const UID = 'api::country.country';

interface SeedCountry {
  code: string;
  name: string;
  order: number;
  active: boolean;
  legalAge: number;
  icon?: { file: string; alt: string };
}

// Fictitious demo data. PE is inactive on purpose to demo FR-006.
const COUNTRIES: SeedCountry[] = [
  { code: 'CO', name: 'Colombia', order: 1, active: true, legalAge: 18, icon: { file: 'co.svg', alt: 'Bandera de Colombia' } },
  { code: 'CL', name: 'Chile', order: 2, active: true, legalAge: 18, icon: { file: 'cl.svg', alt: 'Bandera de Chile' } },
  { code: 'PE', name: 'Perú', order: 3, active: false, legalAge: 18 },
];

async function uploadIcon(strapi: Core.Strapi, file: string, alt: string): Promise<number> {
  // Read from src/ (not dist/) so the SVGs do not need a build copy step.
  const filepath = path.join(strapi.dirs.app.root, 'src', 'seed', 'assets', file);
  const { size } = fs.statSync(filepath);
  const [uploaded] = await strapi.plugin('upload').service('upload').upload({
    data: { fileInfo: { name: file, alternativeText: alt, caption: alt } },
    files: { filepath, originalFilename: file, mimetype: 'image/svg+xml', size },
  });
  return uploaded.id;
}

export async function seedCountries(strapi: Core.Strapi): Promise<void> {
  const total = await strapi.documents(UID).count({});
  if (total > 0) return;

  for (const country of COUNTRIES) {
    const icon = country.icon ? await uploadIcon(strapi, country.icon.file, country.icon.alt) : undefined;
    await strapi.documents(UID).create({
      data: { code: country.code, name: country.name, order: country.order, active: country.active, legalAge: country.legalAge, icon },
      status: 'published',
    });
  }
}
import type { Core } from '@strapi/strapi';

// Actions the Public role needs, each with the reason it is granted.
const PUBLIC_ACTIONS = [
  // The wizard reads the list of available countries (US-00).
  'api::country.country.find',
  // The wizard reads the form fields of the selected country (US-01).
  'api::form-field.form-field.find',
];

export async function grantPublicPermissions(strapi: Core.Strapi): Promise<void> {
  const role = await strapi.db.query('plugin::users-permissions.role').findOne({ where: { type: 'public' } });
  if (!role) return;

  for (const action of PUBLIC_ACTIONS) {
    const existing = await strapi.db
      .query('plugin::users-permissions.permission')
      .findOne({ where: { action, role: role.id } });
    if (!existing) {
      await strapi.db.query('plugin::users-permissions.permission').create({ data: { action, role: role.id } });
    }
  }
}
