import type { Core } from '@strapi/strapi';

const PLAN_UID = 'api::plan.plan';
const COUNTRY_UID = 'api::country.country';

interface SeedPlan {
  name: string;
  shortDescription: string;
  basePrice: number;
  recommended?: boolean;
  active?: boolean;
  coverages: string[];
  benefits: string[];
}

// Fictitious demo data. Order = position in the list.
export const PLANS_BY_COUNTRY: Record<string, SeedPlan[]> = {
  CO: [
    {
      name: 'Básico',
      shortDescription: 'La protección esencial para circular tranquilo.',
      basePrice: 89000,
      coverages: ['Responsabilidad civil', 'Pérdida total por hurto', 'Asistencia jurídica'],
      benefits: ['Grúa en caso de accidente'],
    },
    {
      name: 'Plus',
      shortDescription: 'Cobertura amplia con asistencia todo el año.',
      basePrice: 145000,
      recommended: true,
      coverages: ['Responsabilidad civil', 'Pérdida total por hurto', 'Pérdida parcial por daños', 'Asistencia jurídica'],
      benefits: ['Grúa 24/7', 'Vehículo de reemplazo por 5 días'],
    },
    {
      name: 'Total',
      shortDescription: 'La cobertura más completa, sin deducible en pérdidas totales.',
      basePrice: 210000,
      coverages: [
        'Responsabilidad civil',
        'Pérdida total por hurto',
        'Pérdida parcial por daños',
        'Cobertura de cristales',
        'Asistencia jurídica',
      ],
      benefits: ['Grúa 24/7', 'Vehículo de reemplazo por 15 días', 'Revisión técnica anual'],
    },
    {
      name: 'Clásico',
      shortDescription: 'Plan descontinuado, ya no se ofrece a nuevos clientes.',
      basePrice: 99000,
      active: false,
      coverages: ['Responsabilidad civil', 'Pérdida total por hurto'],
      benefits: ['Grúa en caso de accidente'],
    },
  ],
  CL: [
    {
      name: 'Esencial',
      shortDescription: 'Lo básico para estar protegido en el camino.',
      basePrice: 24990,
      coverages: ['Responsabilidad civil', 'Robo del vehículo'],
      benefits: ['Asistencia en ruta'],
    },
    {
      name: 'Plus',
      shortDescription: 'Equilibrio entre cobertura y precio, con asistencia.',
      basePrice: 39990,
      recommended: true,
      coverages: ['Responsabilidad civil', 'Robo del vehículo', 'Daños propios', 'Defensa jurídica'],
      benefits: ['Asistencia en ruta 24/7', 'Auto de reemplazo por 7 días'],
    },
    {
      name: 'Full',
      shortDescription: 'Protección total para ti y tu vehículo.',
      basePrice: 59990,
      coverages: ['Responsabilidad civil', 'Robo del vehículo', 'Daños propios', 'Cobertura de cristales', 'Defensa jurídica'],
      benefits: ['Asistencia en ruta 24/7', 'Auto de reemplazo por 15 días', 'Lavado mensual'],
    },
  ],
};

/** Seeds the demo plans only when no Plan exists; every plan is published. */
export async function seedPlans(strapi: Core.Strapi): Promise<void> {
  const total = await strapi.documents(PLAN_UID).count({});
  if (total > 0) return;

  for (const [code, plans] of Object.entries(PLANS_BY_COUNTRY)) {
    const country = await strapi.documents(COUNTRY_UID).findFirst({ filters: { code }, status: 'published' });
    if (!country) continue;
    let order = 1;
    for (const plan of plans) {
      await strapi.documents(PLAN_UID).create({
        data: {
          name: plan.name,
          shortDescription: plan.shortDescription,
          basePrice: plan.basePrice,
          order: order++,
          recommended: plan.recommended ?? false,
          active: plan.active ?? true,
          coverages: plan.coverages.map((text) => ({ text })),
          benefits: plan.benefits.map((text) => ({ text })),
          country: country.documentId,
        },
        status: 'published',
      });
    }
  }
}

import { describe, expect, it } from 'vitest';
import { DRIVER_BANDS, VEHICLE_BANDS, pricingPatch } from './countries';

describe('US-02 · FR-004 country pricing backfill (UT-10)', () => {
  it('fills currency, locale and bands when all are missing', () => {
    expect(pricingPatch({ code: 'CL' })).toEqual({
      currency: 'CLP',
      numberLocale: 'es-CL',
      driverAgeBands: DRIVER_BANDS,
      vehicleAgeBands: VEHICLE_BANDS,
    });
  });

  it('never overwrites edited values and fills only what is missing', () => {
    const edited = [{ fromAge: 0, toAge: 99, factor: 1.5 }];
    expect(
      pricingPatch({ code: 'CO', currency: 'USD', numberLocale: 'en-US', driverAgeBands: edited, vehicleAgeBands: [] }),
    ).toEqual({ vehicleAgeBands: VEHICLE_BANDS });
    expect(
      pricingPatch({ code: 'CO', currency: 'COP', numberLocale: 'es-CO', driverAgeBands: edited, vehicleAgeBands: edited }),
    ).toEqual({});
  });
});

import re
def rw(p, f):
    s = open(p, encoding='utf8').read()
    s = f(s)
    open(p, 'w', encoding='utf8').write(s)

def integrity(s):
    s = s.replace("const UID = 'api::form-field.form-field';", "const UID = 'api::form-field.form-field';\nconst PLAN_UID = 'api::plan.plan';")
    s = s.replace("type Ref = string | number;", """/** Pure rule: a plan needs a country, otherwise it silently disappears from every country's list. */
export function checkPlanIntegrity(input: { countryDocumentId?: string | null }): string | null {
  if (!input.countryDocumentId) return 'El plan debe tener un país.';
  return null;
}

type Ref = string | number;""")
    s = s.replace("registerFormFieldIntegrity", "registerCountryIntegrity")
    s = s.replace("    if (context.uid !== UID || !ACTIONS.includes(context.action)) return next();\n",
      "    if (!ACTIONS.includes(context.action)) return next();\n    if (context.uid === PLAN_UID) return checkPlan(strapi, context, next);\n    if (context.uid !== UID) return next();\n")
    s += """
/** Resolves the effective country (payload, else stored) of a plan and applies the Plan rule. */
async function checkPlan(
  strapi: Core.Strapi,
  context: { params?: unknown },
  next: () => Promise<unknown>,
): Promise<unknown> {
  const params = (context.params ?? {}) as { documentId?: string; data?: Record<string, unknown> };
  const { present, ref } = readCountryPayload((params.data ?? {}).country);
  let countryDocumentId: string | null = null;
  if (present) {
    if (typeof ref === 'number') {
      const found = (await strapi.db.query('api::country.country').findOne({ where: { id: ref } })) as {
        documentId: string;
      } | null;
      countryDocumentId = found?.documentId ?? null;
    } else {
      countryDocumentId = ref;
    }
  } else if (params.documentId) {
    const existing = (await strapi.documents(PLAN_UID).findOne({
      documentId: params.documentId,
      populate: { country: { fields: ['documentId'] } },
      status: 'draft',
    })) as { country?: { documentId: string } | null } | null;
    countryDocumentId = existing?.country?.documentId ?? null;
  }
  const message = checkPlanIntegrity({ countryDocumentId });
  if (message) throw new errors.ValidationError(message);
  return next();
}
"""
    return s
rw('../middlewares/country-integrity.ts', integrity)

def tests(s):
    s = s.replace("import { checkFormFieldIntegrity, readCountryPayload } from './form-field-integrity';",
                  "import { checkFormFieldIntegrity, checkPlanIntegrity, readCountryPayload } from './country-integrity';")
    s += """
describe('US-02 · FR-001 plan integrity (UT-09)', () => {
  // The effective country is the payload's when present, else the stored one (null on create).
  const effective = (payload: unknown, stored: string | null) => {
    const { present, ref } = readCountryPayload(payload);
    return present ? (ref === null ? null : String(ref)) : stored;
  };

  it('rejects a plan without country on create, update and publish', () => {
    // create: nothing stored; update/publish: the payload clears the relation, or nothing is stored.
    const cases: Array<[unknown, string | null]> = [
      [undefined, null],
      [null, 'co'],
      [{ set: [] }, 'co'],
      [{ connect: [], disconnect: [{ id: 1 }] }, 'co'],
      [{ connect: [], disconnect: [] }, null],
    ];
    for (const [payload, stored] of cases) {
      expect(checkPlanIntegrity({ countryDocumentId: effective(payload, stored) })).toBe('El plan debe tener un país.');
    }
  });

  it('accepts a save that leaves the country untouched, or sets one', () => {
    expect(checkPlanIntegrity({ countryDocumentId: effective({ connect: [], disconnect: [] }, 'co') })).toBeNull();
    expect(checkPlanIntegrity({ countryDocumentId: effective({ connect: [{ documentId: 'cl' }] }, null) })).toBeNull();
  });
});
"""
    return s
rw('../middlewares/country-integrity.test.ts', tests)

